// board is a flat array of 81 numbers, 0 for blank.
bool solveSudoku(std::array<int, 81>& board) {
    auto candidates = [&](int cell) {
        int row = cell / 9, col = cell % 9;
        int boxRow = (row / 3) * 3, boxCol = (col / 3) * 3;
        std::set<int> taken;

        for (int i = 0; i < 9; i++) {
            taken.insert(board[row * 9 + i]);                              // row
            taken.insert(board[i * 9 + col]);                              // column
            taken.insert(board[(boxRow + i / 3) * 9 + boxCol + i % 3]);    // box
        }

        std::vector<int> out;
        for (int v = 1; v <= 9; v++)
            if (!taken.count(v)) out.push_back(v);
        return out;
    };

    // The heuristic: fewest options first.
    auto pickCell = [&]() {
        int best = -1, bestCount = 10;
        for (int i = 0; i < 81; i++) {
            if (board[i] != 0) continue;
            int count = (int)candidates(i).size();
            if (count < bestCount) {
                best = i;
                bestCount = count;
                if (count == 0) break;   // nothing beats finding this out now
            }
        }
        return best;
    };

    std::function<bool()> solve = [&]() -> bool {
        int cell = pickCell();
        if (cell == -1) return true;     // no blanks left

        for (int v : candidates(cell)) {
            board[cell] = v;             // choose
            if (solve()) return true;    // explore
            board[cell] = 0;             // un-choose
        }

        return false;
    };

    return solve();
}
